def transform(grid):
    h,w=len(grid),len(grid[0]); bg=max(range(10),key=lambda k:sum(v==k for row in grid for v in row))
    # Count rectangular candidate cell support in a fixed box; actual shapes
    # are the large monochrome rectangles, all stray colors are noise.
    boxes=[]
    for color in range(10):
        if color==bg: continue
        # Components connect diagonally too, so noise-colored interruptions
        # don't split the underlying rectangles.
        seen=set()
        for r in range(h):
            for c in range(w):
                if grid[r][c]!=color or (r,c) in seen: continue
                st=[(r,c)]; seen.add((r,c)); cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            yy,xx=y+dy,x+dx
                            if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                                seen.add((yy,xx)); st.append((yy,xx))
                if len(cells)>=4:
                    a=min(y for y,x in cells); b=max(y for y,x in cells); l=min(x for y,x in cells); rr=max(x for y,x in cells)
                    boxes.append((a,b,l,rr,color,len(cells)))
    out=[[bg]*w for _ in range(h)]
    # Enforce disjoint object regions by assigning each occupied coordinate
    # to the same-color candidate with the strongest support.
    for a,b,l,rr,col,n in boxes:
        for r in range(a,b+1):
            for c in range(l,rr+1):
                if out[r][c]==bg: out[r][c]=col
                elif out[r][c]!=col:
                    old=next((x[5] for x in boxes if x[4]==out[r][c] and x[0]<=r<=x[1] and x[2]<=c<=x[3]),0)
                    if n>old: out[r][c]=col
    return out

